import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import type { ThemeName } from './themes';

/**
 * Screenshots generated by `bun run docs:screenshots`.
 *
 * Notes when adding shots:
 * - The first route with a `url` is shown as selected (use `path` or
 *   `selected` to choose another one).
 * - Disable `layout.auto_padding`, there is no dashboard to pad.
 * - Any `mdi:*` icon in the config is fetched automatically.
 * - Viewport width decides desktop vs mobile (`desktop.min_width`, 768px by
 *   default). Mobile cards are edge-to-edge unless `mobile.mode` is
 *   `floating`, so mobile shots usually look best with `phone: true`.
 * - Phone shots enable `mobile.safe_area` (except the shot comparing it): not
 *   the default, but it keeps the home indicator clear of the routes.
 */
export type Panel = {
  /** navbar-card configuration */
  config: Record<string, any>;
  /** Merged into the stubbed `hass` object (states, user, ...) */
  hass?: Record<string, any>;
  /** Index of the route whose popup should be open */
  openPopup?: number;
  /** Page path, for routes selected by path; defaults to the first route's url */
  path?: string;
};

/** A callout naming an element of the card, drawn above or below it */
export type Annotation = {
  /** Text of the callout, e.g. the CSS class */
  label: string;
  /** Selector inside the card's shadow root */
  selector: string;
  /** Which match of the selector, defaults to the first */
  index?: number;
  /** Where the label goes, relative to the card */
  side: 'top' | 'bottom' | 'left' | 'right';
  /** Label row for top/bottom callouts, 1 sits closer to the card than 0 */
  row?: number;
  /** Point the line near the element's left edge instead of its center */
  alignLeft?: boolean;
};

export type Shot = {
  /** Unique name, can be passed on the command line to only render this shot */
  name: string;
  /** Output path, relative to the repository root (dark: `<out>_dark.png`) */
  out: string;
  /** One panel per config; two or more are rendered next to each other */
  panels: Panel[];
  /** Render each config inside the bottom of a mocked phone (mobile mode) */
  phone?: boolean;
  /** Themes to render, defaults to light */
  themes?: ThemeName[];
  /** Stack configs vertically instead of side by side */
  stack?: boolean;
  /** CSS viewport per config, defaults to 1000x600 (or 390x844 with phone) */
  viewport?: { width: number; height: number };
  /** Visible height of the phone's bottom in CSS px, defaults to 150 */
  phoneCrop?: number;
  /** CSS background drawn behind the card (the crop gets rounded corners) */
  background?: string;
  /** Capture the whole viewport as a dashboard screen, not just the card */
  fullscreen?: boolean;
  /** Callouts naming parts of the card (single panel, card mode only) */
  annotations?: Annotation[];
};

