/** Mobile popup with labels, with or without label backgrounds */
const popupLabels = (backgrounds: boolean): Panel => ({
  config: {
    layout: noPadding,
    mobile: {
      safe_area: true,
      show_labels: 'popup_only',
      show_popup_label_backgrounds: backgrounds,
    },
    routes,
  },
  openPopup: MORE,
});

/**
 * Generated album cover (no real artwork). Parentheses are encoded too, the
 * card puts the picture in an unquoted CSS url().
 */
const albumCover = (from: string, to: string) =>
  `data:image/svg+xml,${encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><linearGradient id="g" x2="1" y2="1"><stop offset="0" stop-color="${from}"/><stop offset="1" stop-color="${to}"/></linearGradient></defs><rect width="100" height="100" fill="url(#g)"/><circle cx="50" cy="50" r="22" fill="none" stroke="#fff" stroke-opacity=".6" stroke-width="6"/></svg>`,
  ).replace(/\(/g, '%28').replace(/\)/g, '%29')}`;

/** A playing media_player entity for the stubbed hass.states */
const mediaPlayer = (
  entity_id: string,
  media_title: string,
  media_artist: string,
  cover: string,
) => ({
  attributes: {
    entity_picture: cover,
    media_artist,
    media_duration: 214,
    media_position: 96,
    media_title,
  },
  entity_id,
  state: 'playing',
});
const livingRoom = mediaPlayer(
  'media_player.living_room',
  'Song Title',
  'Artist Name',
  albumCover('#ff9a5a', '#7b3fa0'),
);
const kitchen = mediaPlayer(
  'media_player.kitchen',
  'Another Song',
  'Another Artist',
  albumCover('#4fc3f7', '#1b5e20'),
);

/** Config of an example in docs/examples/, the same file the Examples page shows */
const example = (id: string): Record<string, any> => {
  const config = Bun.YAML.parse(
    readFileSync(join(import.meta.dir, `../../docs/examples/${id}.yaml`), 'utf8'),
  ) as Record<string, any>;
  return { ...config, layout: { ...config.layout, ...noPadding } };
};

